<script setup>
import { useForm,router,Link } from '@inertiajs/vue3'; import AppLayout from '@/Layouts/AppLayout.vue'; import PrimaryButton from '@/Components/PrimaryButton.vue';
const props=defineProps({category:Object,questions:Object}); const form=useForm({question_fr:'',answer_fr:'',question_en:'',answer_en:'',image:null}); const importer=useForm({list:''});
const create=()=>form.post(route('admin.culture-quiz.questions.store',props.category.id),{forceFormData:true,onSuccess:()=>form.reset()});
</script>
<template><AppLayout :title="category.name"><template #header><Link :href="route('admin.culture-quiz.index')" class="font-bold text-violet-600">← Culture Quiz</Link><h2 class="qp-title mt-2">{{category.name}}</h2></template><main class="qp-shell grid gap-7 py-10 lg:grid-cols-2"><form class="qp-card space-y-4" @submit.prevent="create"><h3 class="text-xl font-black">Créer une question bilingue</h3><div v-for="locale in ['fr','en']" :key="locale" class="rounded-2xl bg-violet-50 p-4 dark:bg-white/5"><div class="qp-kicker">{{locale}}</div><textarea v-model="form['question_'+locale]" required class="mt-2 w-full rounded-xl border-slate-300 bg-white text-slate-900 placeholder:text-slate-400 dark:border-white/15 dark:bg-slate-950 dark:text-white dark:placeholder:text-slate-500" placeholder="Question"/><textarea v-model="form['answer_'+locale]" required class="mt-2 w-full rounded-xl border-slate-300 bg-white text-slate-900 placeholder:text-slate-400 dark:border-white/15 dark:bg-slate-950 dark:text-white dark:placeholder:text-slate-500" placeholder="Réponse"/></div><input type="file" accept="image/*" @change="form.image=$event.target.files[0]"><PrimaryButton>Créer</PrimaryButton></form><form class="qp-card" @submit.prevent="importer.post(route('admin.culture-quiz.import',category.id),{onSuccess:()=>importer.reset()})"><h3 class="text-xl font-black">Import rapide</h3><p class="qp-muted mt-2">Une ligne : question || réponse || FR ou EN</p><textarea v-model="importer.list" required rows="12" class="mt-4 w-full rounded-xl border-slate-300 bg-white text-slate-900 placeholder:text-slate-400 dark:border-white/15 dark:bg-slate-950 dark:text-white dark:placeholder:text-slate-500" placeholder="Capitale de la France ? || Paris || FR"/><PrimaryButton class="mt-4">Importer</PrimaryButton></form><section class="qp-card lg:col-span-2"><h3 class="text-xl font-black">Questions ({{questions.total}})</h3><div class="mt-4 divide-y"><article v-for="q in questions.data" :key="q.id" class="flex items-start justify-between gap-4 py-4"><div><p v-for="t in q.translations" :key="t.locale" class="font-bold"><span class="text-xs uppercase text-violet-500">{{t.locale}}</span> {{t.question}} <span class="font-normal text-slate-400">— {{t.answer}}</span></p></div><button class="text-sm font-bold text-rose-500" @click="router.delete(route('admin.culture-quiz.questions.destroy',q.id))">Supprimer</button></article></div></section></main></AppLayout></template>
